/* history */
const snap=()=>JSON.stringify(S.clips);
function push(){hist.push(snap());if(hist.length>60)hist.shift();redo=[]}
function undo(){if(!hist.length)return;redo.push(snap());S.clips=JSON.parse(hist.pop());S.sel=null;rAll()}
