/* render */
const total=()=>Math.max(0,...S.clips.map(c=>c.s+c.d));
const tcf=t=>{const f=set.fps,n=Math.floor(t*f),p=x=>String(x).padStart(2,'0');return p(Math.floor(n/f/60))+':'+p(Math.floor(n/f)%60)+':'+p(n%f)};
