function loop(ts){if(page=='editor'){if(S.playing){S.t+=(ts-last)/1000;if(S.t>=total()){S.t=total();pause();if(rec){rec.stop();rec=null}}else sync(false)}frame()}last=ts;requestAnimationFrame(loop)}
