  row.ondragover=e=>e.preventDefault();row.ondrop=e=>{e.preventDefault();const m=S.media.find(x=>x.id==e.dataTransfer.getData('text/plain'));if(m)addClip(m,tr,Math.max(0,(e.clientX-row.getBoundingClientRect().left)/zoom))};
