/* properties */
const DEF=[['Color grading'],['br','Brightness',0,200,1],['co','Contrast',0,200,1],['sa','Saturation',0,300,1],['Keyframes (start → end)'],['sc0','Scale start',10,300,1],['sc1','Scale end',10,300,1],['x0','X start',-100,100,1],['x1','X end',-100,100,1],['op','Opacity',0,100,1],['Speed & audio'],['spd','Speed',.25,4,.25],['vol','Volume',0,2,.05]];
