 DEF.forEach(r=>{if(r.length==1)return add(`<div class="sec">${r[0]}</div>`);if(c.tr==2&&['br','co','sa','spd','vol'].includes(r[0]))return;add(`<div class="f"><label>${r[1]}</label><input type="range" id="p_${r[0]}" min="${r[2]}" max="${r[3]}" step="${r[4]}"><span id="v_${r[0]}"></span></div>`)});
