const sp=document.createElement('div');sp.id='splash';sp.innerHTML="<div><img src='"+document.querySelector('img.lg').src+"'><b>EditNova Pro</b><i></i></div>";document.body.append(sp);setTimeout(()=>sp.classList.add('out'),900);setTimeout(()=>sp.remove(),1700);
