/* Plugin Center */
let plugRec=null,plugChunks=[];
function initPlugins(){
 const $p=id=>document.getElementById(id);
 if($p('plugins').dataset.ready)return;
 $p('plugins').dataset.ready='1';
 // Plugin Center navigation tabs and quick-control shortcuts.
 const pluginTabs=[...document.querySelectorAll('[data-plugin-tab]')];
 const pluginViews={browse:$p('pluginBrowsePanel'),controls:$p('pluginControlsPanel'),workspace:$p('pluginWorkspacePanel'),help:$p('pluginHelpPanel')};
 const showPluginTab=name=>{set.pluginTab=name;st.set('en_set',set);pluginTabs.forEach(b=>{const active=b.dataset.pluginTab===name;b.classList.toggle('on',active);b.setAttribute('aria-selected',String(active))});Object.entries(pluginViews).forEach(([key,el])=>{if(el)el.hidden=key!==name})};
 pluginTabs.forEach(b=>b.addEventListener('click',()=>showPluginTab(b.dataset.pluginTab)));showPluginTab(set.pluginTab||'browse');
 $p('pluginOpenEditor')?.addEventListener('click',()=>nav('editor'));
 $p('pluginWorkspaceLaunch')?.addEventListener('click',()=>nav('editor'));
 $p('workspaceStartProject')?.addEventListener('click',()=>newProject('Untitled project'));
 $p('workspaceImportMedia')?.addEventListener('click',()=>{nav('editor');setTimeout(()=>document.getElementById('imp')?.click(),100)});
 $p('workspaceTimeline')?.addEventListener('click',()=>nav('editor'));
 $p('workspaceBackPlugins')?.addEventListener('click',()=>nav('plugins'));
 document.querySelectorAll('[data-plugin-jump]').forEach(b=>b.addEventListener('click',()=>{showPluginTab('browse');const ids={text:'pluginTextSection',audio:'pluginAudioSection',more:'pluginMoreSection'};const target=document.getElementById(ids[b.dataset.pluginJump]);target?.scrollIntoView({behavior:'smooth',block:'start'})}));
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 $p('plugPreview').onclick=()=>{const o=$p('plugPreviewOut');o.textContent=$p('plugText').value||' ';o.className='plug-preview anim-'+$p('plugAnim').value+' bg-'+$p('plugBg').value};
 $p('plugEmoji').querySelectorAll('button').forEach(b=>b.onclick=()=>{$p('plugStickerOut').textContent=b.textContent});
 $p('plugStickerCopy').onclick=()=>{navigator.clipboard?.writeText($p('plugStickerOut').textContent);toast('Sticker copied (if clipboard permission is available)')};
 $p('plugLower').onclick=()=>{$p('plugLowerOut').innerHTML=esc($p('plugName').value)+'<small>'+esc($p('plugRole').value)+'</small>'};
 $p('plugCaptionGo').onclick=()=>{const out=$p('plugCaptionOut'),words=$p('plugCaption').value.trim().split(/\s+/);out.innerHTML=words.map((w,i)=>`<span>${esc(w)}</span>`).join(' ');let i=0;const spans=[...out.querySelectorAll('span')];if(set.captionAnimate===false){spans.forEach(s=>s.classList.add('word-on'));return}const tick=()=>{spans.forEach((s,j)=>s.classList.toggle('word-on',j===i));i++;if(i<spans.length)setTimeout(tick,450)};tick()};
 $p('plugAudio').onchange=()=>{const f=$p('plugAudio').files[0];if(!f)return;const url=URL.createObjectURL(f),player=$p('plugAudioPlayer');player.src=url;player.volume=+$p('plugVolume').value/100;player.playbackRate=+$p('plugSpeed').value;
 const ctx=new (window.AudioContext||window.webkitAudioContext)();f.arrayBuffer().then(buf=>ctx.decodeAudioData(buf)).then(audio=>{const data=audio.getChannelData(0),canvas=$p('plugWave'),c=canvas.getContext('2d');c.clearRect(0,0,canvas.width,canvas.height);c.strokeStyle='#39a8ff';c.beginPath();const step=Math.max(1,Math.floor(data.length/canvas.width));for(let x=0;x<canvas.width;x++){let min=1,max=-1;for(let j=0;j<step;j++){let v=data[x*step+j]||0;min=Math.min(min,v);max=Math.max(max,v)}c.moveTo(x,(1+min)*canvas.height/2);c.lineTo(x,(1+max)*canvas.height/2)}c.stroke();ctx.close()}).catch(()=>toast('Could not decode this audio file'))};
 $p('plugVolume').oninput=()=>{if($p('plugAudioPlayer').src)$p('plugAudioPlayer').volume=+$p('plugVolume').value/100};
 $p('plugSpeed').onchange=()=>{$p('plugAudioPlayer').playbackRate=+$p('plugSpeed').value};
 $p('plugRecStart').onclick=async()=>{try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});plugChunks=[];plugRec=new MediaRecorder(stream);plugRec.ondataavailable=e=>{if(e.data.size)plugChunks.push(e.data)};plugRec.onstop=()=>{const blob=new Blob(plugChunks,{type:plugRec.mimeType||'audio/webm'}),url=URL.createObjectURL(blob);$p('plugRecPlay').src=url;$p('plugRecDownload').href=url;$p('plugRecDownload').style.display='inline-block';stream.getTracks().forEach(t=>t.stop());$p('plugRecStatus').textContent='Recording ready — preview or download it.'};plugRec.start();$p('plugRecStart').disabled=true;$p('plugRecStop').disabled=false;$p('plugRecStatus').textContent='Recording…';}catch(e){$p('plugRecStatus').textContent='Microphone access denied or unavailable. Use HTTPS or localhost.'}};
 $p('plugRecStop').onclick=()=>{if(plugRec&&plugRec.state!=='inactive')plugRec.stop();$p('plugRecStart').disabled=false;$p('plugRecStop').disabled=true};
 $p('plugColorGo').onclick=()=>{const v=$p('plugColor').value,o=$p('plugColorOut');o.className='look-preview look-'+v;o.textContent=$p('plugColor').selectedOptions[0].text+' preview'};
 document.querySelectorAll('.plug-size').forEach(b=>b.onclick=()=>{$p('plugSizeOut').textContent='Recommended canvas: '+b.dataset.size});
 const requireProject=()=>{if(!S.id){toast('Create or open a project first');return false}if(page!=='editor'){nav('editor')}return true};
 const addOverlay=(text,opts={})=>{if(!requireProject())return;const c=mk({tr:2,s:S.t,d:opts.d||3,text:String(text).slice(0,180),size:opts.size||56,col:opts.col||'#ffffff',tn:opts.tn||'fade',td:.35,bg:opts.bg||'none',bold:opts.bold!==false,outline:opts.outline!==false,outlineColor:opts.outlineColor||'#000000',x0:opts.x0||0,x1:opts.x1||0,y0:opts.y0||0,y1:opts.y1||0});push();S.clips.push(c);S.sel=c.id;saveP(1);rAll();toast('Styled text added to timeline — select it to edit or move')};
 $p('plugAddText').onclick=()=>{const anim=$p('plugAnim').value;addOverlay($p('plugText').value||'YOUR TEXT HERE',{tn:anim==='typewriter'?'wipe':anim==='bounce'?'slideup':anim==='pop'?'zoom':'none',td:anim==='typewriter'?1.1:.45,bg:$p('plugBg').value})};
 $p('plugAddSticker').onclick=()=>addOverlay($p('plugStickerOut').textContent||'🔥',{size:100,tn:'fade'});
 $p('plugAddLower').onclick=()=>{const name=$p('plugName').value.trim()||'CREATOR',role=$p('plugRole').value.trim()||'';if(!requireProject())return;const start=S.t;push();const main=mk({tr:2,s:start,d:3,text:name.slice(0,80),size:44,col:'#ffffff',tn:'slideup',td:.45,bg:'#0757a6',bold:true,outline:false,x0:0,x1:0,y0:-22,y1:-22});S.clips.push(main);if(role){const sub=mk({tr:2,s:start,d:3,text:role.slice(0,100),size:22,col:'#6fe1ff',tn:'fade',td:.4,bg:'rgba(8,12,25,.9)',bold:true,outline:false,x0:0,x1:0,y0:22,y1:22});S.clips.push(sub)}S.sel=main.id;saveP(1);rAll();toast('Styled lower third added — press Play to see its animation')};
 $p('plugAddCaption').onclick=()=>{const raw=$p('plugCaption').value.trim()||'Caption';const words=raw.split(/\s+/).filter(Boolean).slice(0,32);if(!requireProject())return;const start=S.t;push();const step=.42,wordDur=Math.max(.55,Math.min(1.15,step+.18));words.forEach((word,i)=>{const c=mk({tr:2,s:start+i*step,d:wordDur,text:word.slice(0,48),size:40,col:'#171717',tn:'pop',td:.12,bg:'#ffdf45',bold:true,outline:false,outlineColor:'#000000',x0:0,x1:0,y0:-8,y1:-8});S.clips.push(c)});S.sel=S.clips[S.clips.length-words.length]?.id||S.sel;saveP(1);rAll();toast('Word Highlight Caption added: '+words.length+' animated word clips. Press Play to preview.')} ;
 $p('plugAddAudio').onclick=()=>{if(!requireProject())return;const f=$p('plugAudio').files[0];if(!f)return toast('Choose an audio file first');const url=URL.createObjectURL(f),audio=document.createElement('audio');audio.preload='metadata';audio.onloadedmetadata=()=>{const id=uid(),m={id,name:f.name,type:'audio',dur:audio.duration||5,url};blobs[id]=url;S.media.push(m);addClip(m,3,S.t);saveP(1);rBin();toast('Audio added to timeline')};audio.src=url};
}
